import{z as l,x as B,o as i,c as A,q as s,j as p,D as E,d as t,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Kupiec 回测检验","description":"","frontmatter":{"title":"Kupiec 回测检验","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/kupiec-backtest.md","filePath":"quant/kupiec-backtest.md","lastUpdated":1791413859000}'),c={name:"quant/kupiec-backtest.md"};function u(d,a,f,h,m,D){const r=B("Mermaid");return i(),A("div",null,[a[2]||(a[2]=s('<h1 id="kupiec-回测检验" tabindex="-1">Kupiec 回测检验 <a class="header-anchor" href="#kupiec-回测检验" aria-label="Permalink to &quot;Kupiec 回测检验&quot;">​</a></h1><div class="epigraph"><p>VaR 模型说「99% 的日子亏损不超过 X」，Kupiec 检验问的只有一句：突破次数对得上吗？</p><footer>—— 据 Kupiec (1995) 无条件覆盖检验；Christoffersen (1998) 独立性扩展</footer></div><p><a href="/quant/pfe-ee-profile">PFE 敞口曲线</a>是模型的输出，本课是模型的体检：风险模型给出的 VaR 分位数是否名副其实。缺口是<strong>回测覆盖检验</strong>——把「突破次数」换算成一个能拒绝/不能拒绝的统计量。Kupiec 检验是这一族里最朴素也最常被监管点名的一个。本课只做频率维度，不进 Christoffersen 的独立性维度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>250 个交易日、99% VaR：期望突破 2.5 天。实际突破 5 天，模型坏了还是运气差？拍脑袋定不了。缺口：<strong>把观察频率与名义覆盖率的偏离量化成 p 值</strong>，并给「红区」一个客观边界（Basel 交通灯）。本课不评估突破的聚类（那正是独立性检验的活）。</p><p><span class="marginnote">术语翻译：突破（exception）= 实亏越过 VaR 的日子；覆盖率（coverage）= 名义「不突破概率」，99% VaR 即覆盖率 99%。Kupiec 的原名叫 POF 检验——Proportion of Failures。</span></p><p><span class="marginnote">数字实例：\\(n=250\\)、\\(p=1\\%\\)。突破 \\(x=2\\) 时似然比 \\(LR\\approx 0.11\\)（远小于 3.84，不拒绝）；\\(x=5\\) 时 \\(LR\\approx 1.96\\)——仍未过 3.84，Kupiec 拒绝不了，尽管 Basel 交通灯已亮黄区；\\(x=7\\) 时 \\(LR\\approx 5.5\\)（超过 3.84，5% 水平拒绝）。同样 250 天，「5 次突破」黄区了却告不赢检验——功效不足是频率检验的软肋。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>似然比检验三步：在原假设下突破概率为 \\(p\\)，似然 \\(L_p=(1-p)^{n-x}p^x\\)；不受约束地用样本频率 \\(\\hat p=x/n\\) 算 \\(L_{\\hat p}\\)；取 \\(LR=-2\\ln(L_p/L_{\\hat p})\\)，原假设下渐近 \\(\\chi^2(1)\\)，超 3.84 即 5% 水平拒绝。全程一个公式，任何回测系统都能内嵌。</p>',9)),(i(),p(o,null,{default:E(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%9B%9E%E7%9C%8B%E7%AA%97%E5%8F%A3%20n%20%E5%A4%A9%22%5D%20--%3E%20B%5B%22%E6%95%B0%E7%AA%81%E7%A0%B4%E6%AC%A1%E6%95%B0%20x%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%90%8D%E4%B9%89%20p%20%E4%B8%8E%E7%BB%8F%E9%AA%8C%20x%2Fn%22%5D%0A%20%20C%20--%3E%20D%5B%22%E7%AE%97%20LR%20%3D%20-2%20ln(Lp%2FLp%5E)%22%5D%0A%20%20D%20--%3E%20E%7B%22LR%20%EF%BC%9E%203.84%3F%22%7D%0A%20%20E%20--%3E%7C%22%E6%98%AF%22%7C%20F%5B%22%E6%8B%92%E7%BB%9D%3A%20%E8%A6%86%E7%9B%96%E5%A4%B1%E7%9C%9F%22%5D%0A%20%20E%20--%3E%7C%22%E5%90%A6%22%7C%20G%5B%22%E6%97%A0%E6%B3%95%E6%8B%92%E7%BB%9D%3A%20%E6%A8%A1%E5%9E%8B%E7%95%99%E4%BB%BB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：Kupiec 像投篮命中率质检——教练说「罚球 99% 中」，一个赛季 250 罚只中 243，Kupiec 算的不是「差 7 个球多不多」，而是「若真有 99% 水平，差这么多概率多大」。概率小到说不过去，才判教练吹牛。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[t("检验的力量来自似然比对数刻度的可加性：突破每多一天，\\(LR\\) 增量非线性放大——这正是「黄区红区」的统计底座。Basel 交通灯把 250 天、99% VaR 的突破数分三段（0–4 绿、5–9 黄、≥10 红），与 Kupiec 在不同置信度下的拒绝域大体咬合。但检验只能看"),e("strong",null,"频率"),t("：突破若全挤在危机周（聚类），频率检验可通过而模型早已失效——条件覆盖（Christoffersen）在 \\(LR\\) 上加独立性项，用一阶马尔可夫把「昨天突破是否抬高今天突破概率」也收进检验。")],-1)),(i(),p(o,null,{default:E(()=>[n(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%A2%91%E7%8E%87%E5%AF%B9%E4%BA%86%E5%B0%B1%E5%AE%89%E5%85%A8%3F%22%5D%20--%3E%7C%22%E5%90%A6%22%7C%20R%5B%22%E7%AA%81%E7%A0%B4%E6%97%B6%E7%82%B9%E8%81%9A%E6%88%90%E4%B8%B2%22%5D%0A%20%20R%20--%3E%20S%5B%22%E6%B3%A2%E5%8A%A8%E7%8E%87%E5%93%8D%E5%BA%94%E8%BF%9F%E9%92%9D%22%5D%0A%20%20S%20--%3E%20T%5B%22%E6%9D%A1%E4%BB%B6%E8%A6%86%E7%9B%96%3A%20%E5%8A%A0%E7%8B%AC%E7%AB%8B%E6%80%A7%E9%A1%B9%22%5D%0A%20%20T%20--%3E%20U%5B%22LR%20%E8%81%94%E5%90%88%20%3D%20%E9%A2%91%E7%8E%87%20%2B%20%E7%8B%AC%E7%AB%8B%22%5D%0A%20%20U%20--%3E%20V%5B%22%E4%B8%A4%E9%A1%B9%E9%83%BD%E8%BF%87%E6%89%8D%E6%94%BE%E8%A1%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：把「未拒绝」当「模型正确」——250 天样本对 99% VaR 的检验功效极低，真实覆盖率 98% 的坏模型大概率蒙混过关；另一个是拿多模型里回测最好的那个上线（多重检验偏差），等于把显著性全烧光。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>功效与样本是死结：想以 50% 功效检出 99% 变 98.5% 的漂移，需要约 2000 天——一个完整的信用周期。窗口滚动态的选择（逐日滚动 vs 逐年重置）会改变突破的独立性结构，进而影响第二维检验的适用性。对 ES（期望损失）覆盖率检验没有 Kupiec 式单参数版本，业界的替代是 Acerbi–Szekely 检验量。与模型治理的接口：Kupiec 是「模型退役」的客观依据之一，但不该是唯一——回测只能证明历史，不能担保明天。</p><p><span class="marginnote">直觉类比：Kupiec 是体温计不是 CT——它能便宜地回答「烧没烧」，回答不了「烧在哪」；频率异常先上体温计，定位病因要靠条件覆盖与损益归因这些更贵的检查。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kupiec POF：\\(LR=-2\\ln(L_p/L_{\\hat p})\\)，渐近 \\(\\chi^2(1)\\)，3.84 是 5% 线。</li><li>250 天 99% VaR 的功效极低，未拒绝 ≠ 正确；多重检验会烧掉显著性。</li><li>频率之外还有聚类维度，Christoffersen 条件覆盖补上独立项。</li><li>出处：Kupiec「Techniques for Verifying the Accuracy of Risk Models」1995；Christoffersen 1998；Basel 交通灯框架。</li></ul>',6))])}const x=l(c,[["render",u]]);export{C as __pageData,x as default};
